package com.primehr.performancemanagement.report.application;

import com.primehr.integration.administrative.PermissionDataScope;
import com.primehr.performancemanagement.domain.*;
import com.primehr.performancemanagement.infrastructure.*;
import com.primehr.performancemanagement.report.application.PerformanceFormalReportData.*;
import com.primehr.performancemanagement.report.domain.PerformanceReportMetadataSnapshot;
import com.primehr.performancemanagement.report.domain.PerformanceReportMetadataSnapshot.ReportKind;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.ApplicationConflictException;
import com.primehr.shared.exception.ResourceNotFoundException;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Transactional(readOnly = true)
public class PerformanceFormalReportServiceImpl implements PerformanceFormalReportService {
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("MMM d, uuuu",Locale.ENGLISH);
    private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("MMM d, uuuu h:mm a z",Locale.ENGLISH).withZone(ZoneId.of("Asia/Manila"));
    private final PerformanceCommitmentVersionRepository versions; private final PerformanceCommitmentSectionRepository sections;
    private final PerformanceCommitmentItemRepository items; private final PerformanceMonitoringCaseRepository monitoringCases;
    private final PerformanceMonitoringUpdateRepository updates; private final PerformanceRatingCaseRepository ratingCases;
    private final PerformanceFinalRatingRepository finalRatings; private final PerformanceRatingAssessmentRepository assessments;
    private final PerformanceRatingSourceItemRepository ratingSources;
    private final PerformanceRatingItemResultRepository itemResults; private final PerformanceRatingDimensionResultRepository dimensionResults;
    private final PerformanceCoachingSessionRepository coachingSessions; private final PerformanceCoachingActionItemRepository coachingActions;
    private final PerformanceInterventionRepository interventions; private final PerformanceInterventionCheckpointRepository checkpoints;
    private final PerformanceReportMetadataPreparationService metadata; private final PerformanceFormalReportRenderer renderer;
    private final PrimeHrAuditService audit;

    public PerformanceFormalReportServiceImpl(PerformanceCommitmentVersionRepository versions,PerformanceCommitmentSectionRepository sections,
            PerformanceCommitmentItemRepository items,PerformanceMonitoringCaseRepository monitoringCases,PerformanceMonitoringUpdateRepository updates,
            PerformanceRatingCaseRepository ratingCases,PerformanceFinalRatingRepository finalRatings,PerformanceRatingAssessmentRepository assessments,
            PerformanceRatingSourceItemRepository ratingSources,
            PerformanceRatingItemResultRepository itemResults,PerformanceRatingDimensionResultRepository dimensionResults,
            PerformanceCoachingSessionRepository coachingSessions,PerformanceCoachingActionItemRepository coachingActions,
            PerformanceInterventionRepository interventions,PerformanceInterventionCheckpointRepository checkpoints,
            PerformanceReportMetadataPreparationService metadata,PerformanceFormalReportRenderer renderer,PrimeHrAuditService audit){this.versions=versions;this.sections=sections;this.items=items;this.monitoringCases=monitoringCases;this.updates=updates;this.ratingCases=ratingCases;this.finalRatings=finalRatings;this.assessments=assessments;this.ratingSources=ratingSources;this.itemResults=itemResults;this.dimensionResults=dimensionResults;this.coachingSessions=coachingSessions;this.coachingActions=coachingActions;this.interventions=interventions;this.checkpoints=checkpoints;this.metadata=metadata;this.renderer=renderer;this.audit=audit;}

    @Override public String formTypeForCommitment(String agency,String id){return version(agency,id).getFormType();}
    @Override public String formTypeForFinalRating(String agency,String id){return ratingCase(agency,finalRating(agency,id).getRatingCaseId()).getFormType();}

    @Override public byte[] planningForm(String agency,String id,String token,String actor,PermissionDataScope scope,String correlation){PerformanceCommitmentVersion v=version(agency,id);if(v.getStatus()!=PerformanceCommitmentVersion.Status.APPROVED&&v.getStatus()!=PerformanceCommitmentVersion.Status.SUPERSEDED)throw conflict("A planning form requires an approved commitment revision");ReportKind kind=formKind(v.getFormType());PerformanceReportMetadataSnapshot m=metadata.commitment(agency,kind,v,token,actor,scope);access(m,actor,scope);byte[] pdf=renderer.form(new Form(header(m,v.getFormLabel()+" - PLANNING",v.getFormType(),v.getStatus().name(),ref(v)),null,"NOT YET RATED",formRows(agency,v,Map.of(),null,null)));record(agency,"GENERATE_SPMS_PLANNING_REPORT",id,v.getDefinitionVersion(),v.getVersion(),m,pdf,correlation);return pdf;}

    @Override public byte[] ratedForm(String agency,String id,String token,String actor,PermissionDataScope scope,String correlation){PerformanceFinalRating rating=finalRating(agency,id);PerformanceRatingCase ratingCase=ratingCase(agency,rating.getRatingCaseId());if(ratingCase.getStatus()!=PerformanceRatingCase.Status.FINALIZED)throw conflict("A rated form requires a finalized rating case");PerformanceCommitmentVersion v=version(agency,ratingCase.getCommitmentVersionId());ReportKind kind=formKind(v.getFormType());PerformanceReportMetadataSnapshot m=metadata.finalRating(agency,kind,rating,v,token,actor,scope);access(m,actor,scope);PerformanceRatingAssessment assessment=assessments.findByIdAndAgencyId(rating.getSourceAssessmentId(),agency).orElseThrow(()->notFound("Final assessment was not found"));Map<String,PerformanceRatingSourceItem> sourceById=ratingSources.findByAgencyIdAndRatingCaseIdOrderByCommitmentSectionIdAscDisplayOrderAsc(agency,ratingCase.getId()).stream().collect(Collectors.toMap(PerformanceRatingSourceItem::getId,Function.identity()));Map<String,String> accomplishments=sourceById.values().stream().collect(Collectors.toMap(PerformanceRatingSourceItem::getCommitmentItemId,PerformanceRatingSourceItem::getAccomplishmentNarrative));Map<String,PerformanceRatingItemResult> scores=itemResults.findByAgencyIdAndAssessmentId(agency,assessment.getId()).stream().collect(Collectors.toMap(result->{PerformanceRatingSourceItem source=sourceById.get(result.getSourceItemId());if(source==null)throw conflict("Final rating item source is missing");return source.getCommitmentItemId();},Function.identity()));Map<String,List<PerformanceRatingDimensionResult>> dimensions=dimensionResults.findByAgencyIdAndAssessmentId(agency,assessment.getId()).stream().collect(Collectors.groupingBy(PerformanceRatingDimensionResult::getItemResultId));byte[] pdf=renderer.form(new Form(header(m,v.getFormLabel()+" - RATED",v.getFormType(),"FINALIZED REVISION "+rating.getRevisionNo(),ref(rating)),rating.getRoundedScore(),rating.getRatingLabel(),formRows(agency,v,accomplishments,scores,dimensions)));record(agency,"GENERATE_SPMS_RATED_REPORT",id,rating.getRevisionNo(),rating.getVersion(),m,pdf,correlation);return pdf;}

    @Override public byte[] monitoring(String agency,String id,String token,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringCase c=monitoringCases.findByIdAndAgencyId(id,agency).orElseThrow(()->notFound("Performance monitoring case was not found"));if(c.getAccomplishmentRevision()<1)throw conflict("A monitoring report requires submitted accomplishments");PerformanceCommitmentVersion v=version(agency,c.getCommitmentVersionId());PerformanceReportMetadataSnapshot m=metadata.monitoring(agency,c,v,token,actor,scope);access(m,actor,scope);Map<String,PerformanceCommitmentItem> byId=items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(agency,v.getId()).stream().collect(Collectors.toMap(PerformanceCommitmentItem::getId,Function.identity()));List<MonitoringRow> rows=new ArrayList<>();int n=1;for(PerformanceMonitoringUpdate u:visibleUpdates(agency,id)){PerformanceCommitmentItem item=byId.get(u.getCommitmentItemId());rows.add(new MonitoringRow(n++,date(u.getReportingDate()),item==null?"Unavailable source item":item.getOutputDescription(),u.getNarrativeAccomplishment(),number(u.getAccomplishedValue()),percent(u.getProgressPercent()),safe(u.getIssuesRisks()),safe(u.getSupportNeeded()),safe(u.getEmployeeRemarks()),u.getStatus().name()));}byte[] pdf=renderer.monitoring(new Monitoring(header(m,"PERFORMANCE MONITORING AND ACCOMPLISHMENT REPORT",v.getFormType(),c.getStatus().name(),ref(c)),rows));record(agency,"GENERATE_SPMS_MONITORING_REPORT",id,c.getAccomplishmentRevision(),c.getVersion(),m,pdf,correlation);return pdf;}

    @Override public byte[] coaching(String agency,String id,String token,String actor,PermissionDataScope scope,String correlation){PerformanceCoachingSession s=coachingSessions.findByIdAndAgencyId(id,agency).orElseThrow(()->notFound("Performance coaching session was not found"));if(s.getStatus()==PerformanceCoachingSession.Status.DRAFT||s.getStatus()==PerformanceCoachingSession.Status.VOIDED)throw conflict("A coaching report requires an issued employee-visible session");PerformanceMonitoringCase c=monitoringCases.findByIdAndAgencyId(s.getMonitoringCaseId(),agency).orElseThrow(()->notFound("Performance monitoring case was not found"));PerformanceCommitmentVersion v=version(agency,c.getCommitmentVersionId());PerformanceReportMetadataSnapshot m=metadata.coaching(agency,s,v,token,actor,scope);access(m,actor,scope);List<ActionRow> rows=new ArrayList<>();int n=1;for(PerformanceCoachingActionItem a:coachingActions.findByAgencyIdAndCoachingSessionIdOrderByDueDateAsc(agency,id))rows.add(new ActionRow(n++,a.getDescription(),a.getAccountableEmployeeNo(),date(a.getDueDate()),a.getStatus().name(),safe(a.getProgressNote()),a.getVerifiedAt()==null?"NOT VERIFIED":"Verified by "+safe(a.getVerifiedBy())+" at "+time(a.getVerifiedAt())));Coaching data=new Coaching(header(m,"PERFORMANCE COACHING RECORD",v.getFormType(),s.getStatus().name(),ref(s)),s.getAgenda(),s.getGoal(),s.getObservedIssue(),s.getAgreedAction(),safe(s.getResourcesSupport()),date(s.getActionDueDate()),time(s.getNextMeetingAt()),safe(s.getEmployeeVisibleFeedback()),safe(s.getEmployeeResponse()),rows);byte[] pdf=renderer.coaching(data);record(agency,"GENERATE_SPMS_COACHING_REPORT",id,s.getRevisionNo(),s.getVersion(),m,pdf,correlation);return pdf;}

    @Override public byte[] intervention(String agency,String id,boolean development,String token,String actor,PermissionDataScope scope,String correlation){PerformanceIntervention i=interventions.findByIdAndAgencyId(id,agency).orElseThrow(()->notFound("Performance intervention was not found"));if(i.getStatus()==PerformanceIntervention.Status.OPEN)throw conflict("An intervention report requires an issued plan");ReportKind kind=development?ReportKind.DEVELOPMENT_PLAN:ReportKind.INTERVENTION;PerformanceRatingCase ratingCase=ratingCase(agency,i.getRatingCaseId());PerformanceCommitmentVersion v=version(agency,ratingCase.getCommitmentVersionId());PerformanceReportMetadataSnapshot m=metadata.intervention(agency,kind,i,v,token,actor,scope);access(m,actor,scope);List<CheckpointRow> rows=new ArrayList<>();int n=1;for(PerformanceInterventionCheckpoint c:checkpoints.findByAgencyIdAndInterventionIdOrderByDueOnAsc(agency,id))rows.add(new CheckpointRow(n++,date(c.getDueOn()),c.getObjective(),c.getStatus().name(),safe(c.getProgressNote()),safe(c.getEmployeeVisibleFeedback())));String purpose=development?"INDIVIDUAL DEVELOPMENT PLAN":"PERFORMANCE INTERVENTION / IMPROVEMENT PLAN";Intervention data=new Intervention(header(m,purpose,v.getFormType(),i.getStatus().name(),ref(i)),purpose,i.getAction().name(),i.getObjectives(),i.getSupportPlan(),i.getAccountableEmployeeNo(),date(i.getStartsOn())+" to "+date(i.getEndsOn()),safe(i.getEmployeeResponse()),i.getClosedAt()==null?"OPEN LIFECYCLE":safe(i.getClosureReason())+" ("+time(i.getClosedAt())+")",rows);byte[] pdf=renderer.intervention(data);record(agency,development?"GENERATE_SPMS_DEVELOPMENT_PLAN":"GENERATE_SPMS_INTERVENTION_REPORT",id,1,i.getVersion(),m,pdf,correlation);return pdf;}

    private List<FormRow> formRows(String agency,PerformanceCommitmentVersion v,Map<String,String> accomplishments,Map<String,PerformanceRatingItemResult> scores,Map<String,List<PerformanceRatingDimensionResult>> dimensions){Map<String,String> sectionNames=sections.findByAgencyIdAndCommitmentVersionIdOrderByDisplayOrder(agency,v.getId()).stream().collect(Collectors.toMap(PerformanceCommitmentSection::getId,PerformanceCommitmentSection::getTitle));List<FormRow> rows=new ArrayList<>();int n=1;for(PerformanceCommitmentItem item:items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(agency,v.getId())){PerformanceRatingItemResult score=scores==null?null:scores.get(item.getId());String dimension="";if(score!=null&&dimensions!=null)dimension=dimensions.getOrDefault(score.getId(),List.of()).stream().sorted(Comparator.comparing(PerformanceRatingDimensionResult::getDimensionCode)).map(d->d.getDimensionCode()+": "+number(d.getNumericScore())).collect(Collectors.joining(" | "));rows.add(new FormRow(n++,sectionNames.getOrDefault(item.getCommitmentSectionId(),""),item.getOutputDescription(),item.getPerformanceIndicator()+"\n"+item.getSuccessStatement(),target(item),accomplishments.getOrDefault(item.getId(),""),dimension,item.getWeightPercent(),score==null?null:score.getRoundedScore(),safe(item.getPlanningRemarks())));}return rows;}
    private List<PerformanceMonitoringUpdate> visibleUpdates(String agency,String caseId){return updates.findByAgencyIdAndMonitoringCaseIdOrderByCreatedAtAsc(agency,caseId).stream().filter(u->u.getStatus()!=PerformanceMonitoringUpdate.Status.DRAFT&&u.getStatus()!=PerformanceMonitoringUpdate.Status.VOIDED&&u.getStatus()!=PerformanceMonitoringUpdate.Status.SUPERSEDED).toList();}
    private static void access(PerformanceReportMetadataSnapshot m,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return;if(m.getEmployeeNo().equalsIgnoreCase(actor))return;if(scope==PermissionDataScope.ASSIGNED_RECORDS&&(equals(actor,m.getSupervisorEmployeeNo())||equals(actor,m.getApproverEmployeeNo())))return;throw new AccessDeniedException("Report is outside the permitted record scope");}
    private void record(String agency,String action,String id,int business,long record,PerformanceReportMetadataSnapshot m,byte[] pdf,String correlation){audit.record(agency,action,"SPMS_FORMAL_REPORT",id,business,record,null,Map.of("reportKind",m.getReportKind().name(),"metadataFingerprint",m.getMetadataFingerprint(),"pdfSha256",sha(pdf)),null,correlation);}
    private PerformanceCommitmentVersion version(String agency,String id){return versions.findByIdAndAgencyId(id,agency).orElseThrow(()->notFound("Performance commitment version was not found"));}private PerformanceFinalRating finalRating(String agency,String id){return finalRatings.findByIdAndAgencyId(id,agency).orElseThrow(()->notFound("Final performance rating was not found"));}private PerformanceRatingCase ratingCase(String agency,String id){return ratingCases.findByIdAndAgencyId(id,agency).orElseThrow(()->notFound("Performance rating case was not found"));}
    private static ReportKind formKind(String form){try{return ReportKind.valueOf(form);}catch(RuntimeException e){throw new IllegalArgumentException("Only OPCR, DPCR, or IPCR commitments have a formal SPMS form");}}
    private static Header header(PerformanceReportMetadataSnapshot m,String title,String form,String state,String source){String org=join(m.getAreaName(),m.getBusinessUnitName());return new Header(title,form,state,m.getAgencyName(),safe(m.getAgencyAddress()),m.getEmployeeNo(),m.getEmployeeName(),m.getPositionName(),org,date(m.getPeriodStart())+" to "+date(m.getPeriodEnd()),person(m.getSupervisorName(),m.getSupervisorPositionName()),person(m.getApproverName(),m.getApproverPositionName()),source,m.getMetadataFingerprint()+"; captured "+time(m.getCapturedAt())+" by "+m.getCapturedBy(),"Generated "+time(Instant.now()));}
    private static String target(PerformanceCommitmentItem i){String value=i.getCommittedValue()!=null?number(i.getCommittedValue()):i.getCommittedFrom()!=null||i.getCommittedTo()!=null?number(i.getCommittedFrom())+" to "+number(i.getCommittedTo()):"";return join(value,i.getUnitOfMeasure(),i.getTargetStart()==null?null:date(i.getTargetStart())+" to "+date(i.getTargetEnd()),i.getDeliverableClarification());}
    private static String ref(Object source){if(source instanceof PerformanceCommitmentVersion v)return "Commitment "+v.getId()+" v"+v.getDefinitionVersion()+"; "+v.getContentFingerprint();if(source instanceof PerformanceFinalRating r)return "Final rating "+r.getId()+" revision "+r.getRevisionNo()+"; "+r.getCalculationFingerprint();if(source instanceof PerformanceMonitoringCase c)return "Monitoring "+c.getId()+" accomplishment revision "+c.getAccomplishmentRevision()+"; "+c.getCommitmentFingerprint();if(source instanceof PerformanceCoachingSession s)return "Coaching "+s.getId()+" revision "+s.getRevisionNo();PerformanceIntervention i=(PerformanceIntervention)source;return "Intervention "+i.getId()+" record version "+i.getVersion();}
    private static String person(String name,String position){return name==null?"":join(name,position);}private static String join(String... values){return Arrays.stream(values).filter(v->v!=null&&!v.isBlank()).collect(Collectors.joining(" | "));}private static String safe(String v){return v==null?"":v;}private static boolean equals(String a,String b){return b!=null&&b.equalsIgnoreCase(a);}private static String date(LocalDate d){return d==null?"":DATE.format(d);}private static String time(Instant i){return i==null?"":TIME.format(i);}private static String number(BigDecimal n){return n==null?"":n.stripTrailingZeros().toPlainString();}private static String percent(BigDecimal n){return n==null?"":number(n)+"%";}private static String sha(byte[] bytes){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}}private static ApplicationConflictException conflict(String m){return new ApplicationConflictException(m);}private static ResourceNotFoundException notFound(String m){return new ResourceNotFoundException(m);}
}
